
window.FullCalendar = {
    Calendar: class {
        constructor(el, options) {
            this.el = el;
            this.options = options || {};
        }
        render() {
            if (!this.el) return;
            const events = this.options.events || [];
            let html = '<div class="p-3 bg-light rounded border"><h5 class="fw-bold text-primary mb-3"><i class="fa-solid fa-calendar-days me-2"></i> Event Calendar Grid</h5><div class="row g-2">';
            events.forEach(e => {
                html += `<div class="col-md-6"><div class="p-2 bg-white rounded border border-start border-4 border-primary"><div class="fw-bold text-dark">${e.title}</div><small class="text-muted">${e.start}</small></div></div>`;
            });
            html += '</div></div>';
            this.el.innerHTML = html;
        }
    }
};
